      "O Direito Penal moderno se organiza em torno de princípios que limitam o poder do Estado de punir — eles existem para proteger o cidadão de arbitrariedades, não para facilitar a vida de quem comete crimes. O mais importante é o princípio da legalidade: não há crime sem lei anterior que o defina, nem pena sem prévia cominação legal (nullum crimen, nulla poena sine lege).",
      "Decorrente da legalidade está o princípio da anterioridade: a lei que define o crime e comina a pena precisa existir antes da conduta ser praticada. Ligado a isso, o princípio da irretroatividade impede que uma lei penal mais gravosa (que piora a situação do réu) retroaja para alcançar fatos anteriores à sua vigência — mas a lei penal mais benéfica (que favorece o réu) sempre retroage, mesmo depois do trânsito em julgado.",
      "Outros princípios centrais: intervenção mínima (o Direito Penal só deve atuar quando outros ramos do direito forem insuficientes para proteger o bem jurídico), fragmentariedade (o Direito Penal protege só os bens jurídicos mais relevantes, de forma fragmentada, não tudo), e proporcionalidade (a pena deve ser proporcional à gravidade do fato)."
