    "corpo": [
      "Depois de constatado o fato típico, o segundo filtro é a ilicitude (ou antijuridicidade): a conduta típica contraria o ordenamento jurídico? Existem quatro causas que excluem a ilicitude, tornando a conduta típica lícita: estado de necessidade, legítima defesa, estrito cumprimento do dever legal e exercício regular de direito.",
      "Legítima defesa exige: agressão injusta, atual ou iminente, a direito próprio ou de outrem, repelida com uso moderado dos meios necessários. É a excludente mais cobrada em concursos policiais — o requisito 'meios necessários usados moderadamente' é o que mais gera controvérsia e questão de prova (o chamado excesso, que retira a excludente e gera responsabilização).",
      "Estado de necessidade exige um conflito entre bens jurídicos, em que o agente sacrifica um bem menor (ou de igual valor) para salvar outro de perigo atual, não provocado voluntariamente por ele, quando não havia outra forma razoável de agir. A diferença central para a legítima defesa é que, no estado de necessidade, o perigo não vem de uma agressão humana injusta — pode vir de força da natureza, de animal, ou até de terceiro inocente."
    ],
    "pontosChave": [
      "Legítima defesa: agressão injusta, atual/iminente, repelida com meios necessários usados moderadamente.",
      "Estado de necessidade: conflito de bens jurídicos diante de perigo atual não provocado voluntariamente pelo agente.",
      "Excesso (doloso ou culposo) em qualquer excludente retira a exclusão de ilicitude e gera responsabilização."
    ],
    "checkRapido": {
      "pergunta": "Um policial já dominou completamente um suspeito, algemado e sem qualquer capacidade de reação, e mesmo assim continua a agredi-lo. Essa conduta posterior à dominação é:",
      "opcoes": [
        "Ainda amparada por legítima defesa, pois o suspeito era perigoso",
        "Excesso, que retira a excludente e gera responsabilização do policial",
        "Estrito cumprimento do dever legal, pois é policial em serviço"
      ],
      "correta": 1,
      "justificativa": "Uma vez cessada a agressão injusta (suspeito já dominado e sem capacidade de reação), não há mais atualidade na agressão — qualquer ato de violência posterior configura excesso, retirando a proteção da legítima defesa e gerando responsabilização penal do agente."
    },
    "oQueCobra": "Diferenciar os requisitos de cada excludente de ilicitude e identificar quando ocorre excesso, que retira a proteção legal.",
    "precisaSaberAntes": "Entender a diferença entre agressão (ato humano injusto) e perigo (situação de risco que pode não vir de ação humana injusta).",
    "explicacao": [
      {
        "titulo": "Estrito cumprimento do dever legal e exercício regular de direito",
        "texto": "Estrito cumprimento do dever legal ampara agentes públicos que, no exercício de suas funções, praticam conduta tipicamente prevista em lei (o policial que prende em flagrante pratica constrangimento, mas amparado pela excludente). Exercício regular de direito ampara qualquer pessoa que exerce uma faculdade prevista em lei, sem abuso (o dono de imóvel que usa força moderada para expulsar invasor)."
      },
      {
        "titulo": "Legítima defesa putativa — quando o agente se engana",
        "texto": "Se o agente, por erro plenamente justificado pelas circunstâncias, acredita estar sob agressão injusta que na verdade não existe, incide em descriminante putativa — dependendo da natureza do erro, pode excluir o dolo (erro de tipo permissivo) ou apenas a culpabilidade (erro de proibição), mas não é tratada como legítima defesa real."
      }
    ],
    "comoIdentificar": "Casos concretos com policial em confronto, invasão de propriedade ou situação de risco iminente testam qual excludente se aplica e se há excesso.",
    "pegadinhas": [
      "Aplicar legítima defesa a uma agressão que já cessou (aí é excesso, não mais legítima defesa).",
      "Confundir estado de necessidade (perigo, não necessariamente de origem humana injusta) com legítima defesa (agressão humana injusta).",
      "Não reconhecer o excesso doloso/culposo como fator que retira a excludente."
    ],
    "resumoFrase": "As quatro excludentes de ilicitude têm requisitos próprios; o excesso em qualquer uma delas retira a proteção e gera responsabilização.",
