    "title": "Erro de tipo e erro de proibição",
    "assunto": "Teoria do erro",
    "tecnica": "Localização do elemento afetado pelo erro",
    "competencia": "Diferenciar erro de tipo (exclui dolo) de erro de proibição (afeta culpabilidade)",
    "dificuldade": "Difícil",
    "tempoLeituraMin": 8,
