    "title": "Iter criminis: tentativa, consumação e desistência voluntária",
    "assunto": "Iter criminis",
    "tecnica": "Identificação da fase do percurso do crime",
    "competencia": "Diferenciar tentativa, consumação, desistência voluntária e arrependimento eficaz",
    "dificuldade": "Média",
    "tempoLeituraMin": 8,
    "tempoExercicioMin": 6,
    "bancaRatings": {
      "FGV": 4,
      "CESPE": 5,
      "FCC": 4,
      "ENEM": 1
    },
    "termosChave": [
      "tentativa",
      "consumação",
      "desistência voluntária"
    ],
    "corpo": [
      "Iter criminis é o caminho percorrido pelo crime, desde a ideia até a consumação: cogitação (fase mental, nunca punível), preparação (atos que organizam a execução, em regra não puníveis, salvo quando a lei antecipa a punição), execução (início dos atos que atacam diretamente o bem jurídico) e consumação (todos os elementos do tipo penal realizados).",
      "Tentativa ocorre quando o agente inicia a execução, mas o crime não se consuma por circunstâncias alheias à sua vontade — a pena é a do crime consumado, reduzida de um a dois terços, conforme a proximidade da consumação. Se o crime não se consuma porque o próprio agente decide parar (e não por circunstância externa), não há tentativa: há desistência voluntária ou arrependimento eficaz.",
      "Desistência voluntária ocorre quando o agente, ainda durante a execução, decide voluntariamente não continuar — ele só responde pelos atos já praticados até ali. Arrependimento eficaz ocorre quando o agente já terminou a execução, mas atua voluntariamente para impedir o resultado (ex.: dá o tiro, mas depois socorre a vítima a tempo de evitar a morte) — também só responde pelos atos já praticados, não pelo crime que pretendia inicialmente."
    ],
    "pontosChave": [
      "Tentativa: execução iniciada, não consumada por circunstância alheia à vontade do agente.",
      "Desistência voluntária: agente para por vontade própria durante a execução — responde só pelos atos já praticados.",
      "Arrependimento eficaz: execução terminada, mas agente impede o resultado voluntariamente — mesma consequência."
    ],
    "checkRapido": {
      "pergunta": "Um atirador dispara contra a vítima, atingindo-a, mas em seguida, arrependido, a leva ao hospital a tempo de salvá-la. Ele responde por:",
      "opcoes": [
        "Tentativa de homicídio",
        "Lesão corporal (pelos atos já praticados), não por tentativa de homicídio",
        "Homicídio consumado, pois já houve disparo e ferimento"
      ],
      "correta": 1,
      "justificativa": "Como a execução já havia sido concluída (o tiro foi disparado) e o agente agiu voluntariamente para impedir o resultado morte, configura-se arrependimento eficaz — ele responde apenas pelos atos já praticados (lesão corporal), não pela tentativa de homicídio que pretendia inicialmente."
    },
    "oQueCobra": "Diferenciar tentativa (interrupção por circunstância externa) de desistência voluntária/arrependimento eficaz (interrupção por vontade própria).",
    "precisaSaberAntes": "Reconhecer se o crime é de execução instantânea ou se admite atos intermediários que possam ser interrompidos.",
    "explicacao": [
      {
        "titulo": "Teste da voluntariedade — a chave para diferenciar",
        "texto": "Pergunte: por que o crime não se consumou? Se a resposta é 'porque algo/alguém externo impediu' (a vítima reagiu, a polícia chegou, a arma falhou), é tentativa. Se a resposta é 'porque o próprio agente decidiu parar ou reverter', é desistência voluntária ou arrependimento eficaz."
      },
      {
        "titulo": "Arrependimento posterior — não confundir com arrependimento eficaz",
        "texto": "Arrependimento posterior é diferente: aplica-se a crimes já consumados sem violência ou grave ameaça à pessoa, quando o agente repara o dano ou restitui a coisa até o recebimento da denúncia — gera apenas redução de pena (um a dois terços), não exclusão do crime consumado, como ocorre no arrependimento eficaz."
      }
    ],
    "comoIdentificar": "Casos concretos que descrevem uma sequência de atos até um resultado (ou sua ausência) testam essa distinção — muito comum em concurso policial.",
    "pegadinhas": [
      "Confundir arrependimento eficaz (durante/após execução, exclui o crime pretendido) com arrependimento posterior (crime já consumado, sem violência, só reduz pena).",
      "Tratar como tentativa uma interrupção que, na verdade, foi decisão voluntária do próprio agente.",
      "Esquecer que crime consumado por violência ou grave ameaça não admite o benefício do arrependimento posterior."
    ],
    "resumoFrase": "Se o crime parou por causa externa, é tentativa; se parou por vontade do próprio agente, é desistência voluntária ou arrependimento eficaz.",
