    "explicacaoComoSeTivesse12": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Iter criminis: tentativa, consumação e desistência voluntária\", a ideia principal é: Iter criminis é o caminho percorrido pelo crime, desde a ideia até a consumação: cogitação (fase mental, nunca punível), preparação (atos que organizam a execução, em regra não puníveis, salvo quando a lei antecipa a punição), execução (início dos atos que. Para estudar sem travar, guarde primeiro estas palavras-chave: tentativa, consumação, desistência voluntária. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Se o crime parou por causa externa, é tentativa; se parou por vontade do próprio agente, é desistência voluntária ou arrependimento eficaz.",
